package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.mappers.AgenteImpresionMapper;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.security.TenantContext;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.domain.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PrintAgentAdminService {
    private final CashRegisterRepository cajas;
    private final AgenteImpresionRepository agentes;private final VinculacionAgenteImpresionRepository pairings;private final CredencialAgenteImpresionRepository credenciales;private final SucursalRepository sucursales;private final AgenteImpresionMapper mapper;private final PrintAgentNumberService numeros;private final PrintAgentTokenService tokens;private final AuditoriaService auditoria;private final Duration vidaCodigo;private final Duration toleranciaConexion;
    public PrintAgentAdminService(CashRegisterRepository cajas,AgenteImpresionRepository agentes,VinculacionAgenteImpresionRepository pairings,CredencialAgenteImpresionRepository credenciales,SucursalRepository sucursales,AgenteImpresionMapper mapper,PrintAgentNumberService numeros,PrintAgentTokenService tokens,AuditoriaService auditoria,@Value("${contacloud.print-agents.pairing-ttl:PT10M}")Duration vidaCodigo,@Value("${contacloud.print-agents.connected-tolerance:PT2M}")Duration toleranciaConexion){this.cajas=cajas;this.agentes=agentes;this.pairings=pairings;this.credenciales=credenciales;this.sucursales=sucursales;this.mapper=mapper;this.numeros=numeros;this.tokens=tokens;this.auditoria=auditoria;this.vidaCodigo=vidaCodigo;this.toleranciaConexion=toleranciaConexion;}
    @Transactional(readOnly=true) @PreAuthorize("hasAuthority('agentes_impresion.ver')") public Page<AgenteImpresionDto> buscar(String buscar,EstadoAgenteImpresion estado,int pagina,int tamano){var p=TenantContext.principalActual();Page<AgenteImpresion> page=agentes.buscar(p.tenantId(),p.empresaId(),limpiar(buscar),estado,PageRequest.of(Math.max(0,pagina),permitido(tamano),Sort.by(Sort.Order.desc("creadoEn"),Sort.Order.desc("id"))));Set<UUID> ids=page.stream().map(AgenteImpresion::getSucursalId).collect(Collectors.toSet());Map<UUID,String> branches=sucursales.findAllByIdInAndEmpresaId(ids,p.empresaId()).stream().collect(Collectors.toMap(Sucursal::getId,Sucursal::getNombre));OffsetDateTime now=OffsetDateTime.now();return page.map(a->mapper.toDto(a,branches.getOrDefault(a.getSucursalId(),"—"),toleranciaConexion,now));}
    @Transactional(readOnly=true) @PreAuthorize("hasAuthority('agentes_impresion.ver')") public AgenteImpresionDto obtener(UUID id){var p=TenantContext.principalActual();AgenteImpresion a=agentes.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("No se encontró el agente de impresión."));String branch=sucursales.findByIdAndEmpresaId(a.getSucursalId(),p.empresaId()).map(Sucursal::getNombre).orElse("—");return mapper.toDto(a,branch,toleranciaConexion,OffsetDateTime.now());}
    @Transactional @PreAuthorize("hasAuthority('agentes_impresion.crear')") public AgenteImpresionDto crear(CrearAgenteImpresionInput input){if(input==null||input.nombre()==null||input.nombre().isBlank()||input.nombre().trim().length()>150)throw new ReglaNegocioException("Indica un nombre de agente válido.");var p=TenantContext.principalActual();Sucursal branch=sucursales.findByIdAndEmpresaId(input.sucursalId(),p.empresaId()).filter(Sucursal::isActivo).orElseThrow(()->new ReglaNegocioException("Selecciona una sucursal activa."));validarCaja(input.cajaId(),input.sucursalId());AgenteImpresion agent=mapper.toEntity(input,p.tenantId(),p.empresaId(),numeros.siguiente(p.tenantId(),p.empresaId()),p.usuarioId());agent=agentes.saveAndFlush(agent);auditoria.registrar("AgentCreated","PrintAgent",agent.getId(),"{}");return mapper.toDto(agent,branch.getNombre(),toleranciaConexion,OffsetDateTime.now());}
    @Transactional @PreAuthorize("hasAuthority('agentes_impresion.codigo')") public CodigoVinculacionDto generarCodigo(UUID id){var p=TenantContext.principalActual();AgenteImpresion agent=agentes.bloquear(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("No se encontró el agente de impresión."));agent.prepararRevinculacion();OffsetDateTime now=OffsetDateTime.now();pairings.invalidarActivas(p.tenantId(),p.empresaId(),id,now);String code=nuevoCodigo();VinculacionAgenteImpresion pairing=pairings.saveAndFlush(new VinculacionAgenteImpresion(p.tenantId(),p.empresaId(),id,tokens.hashCodigo(code),now.plus(vidaCodigo),p.usuarioId()));auditoria.registrar("PairingCodeGenerated","PrintAgent",id,"{\"pairingId\":\""+pairing.getId()+"\"}");return new CodigoVinculacionDto(id,code,pairing.getExpiraEn());}
    @Transactional @PreAuthorize("hasAuthority('agentes_impresion.revocar')") public AgenteImpresionDto revocar(UUID id){var p=TenantContext.principalActual();AgenteImpresion agent=agentes.bloquear(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("No se encontró el agente de impresión."));if(agent.getEstado()!=EstadoAgenteImpresion.REVOKED){OffsetDateTime now=OffsetDateTime.now();agent.revocar(p.usuarioId());pairings.invalidarActivas(p.tenantId(),p.empresaId(),id,now);credenciales.revocarActivas(p.tenantId(),p.empresaId(),id,now);agentes.saveAndFlush(agent);auditoria.registrar("AgentRevoked","PrintAgent",id,"{}");}return obtener(id);}
    @Transactional(readOnly=true) @PreAuthorize("hasAuthority('agentes_impresion.crear')") public List<OpcionSucursal> sucursales(){UUID empresa=TenantContext.requerirEmpresaId();return sucursales.findAllByEmpresaIdAndActivoTrueOrderByNombre(empresa).stream().filter(s->com.citacloud.springboot.contacloud.app.security.EmpresaContext.permiteSucursal(s.getId())).map(s->new OpcionSucursal(s.getId(),s.getNombre())).toList();}
    @Transactional(readOnly=true) @PreAuthorize("hasAuthority('agentes_impresion.ver')") public String nombreCaja(UUID id){if(id==null)return "Sin asignar";var p=TenantContext.principalActual();return cajas.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).filter(c->com.citacloud.springboot.contacloud.app.security.EmpresaContext.permiteSucursal(c.getSucursalId())).map(Caja::getNombre).orElse("Sin asignar");}
    private String nuevoCodigo(){for(int i=0;i<100;i++){String code=tokens.nuevoCodigoVinculacion();if(!pairings.existsByHashCodigo(tokens.hashCodigo(code)))return code;}throw new ReglaNegocioException("No fue posible generar el código. Intenta nuevamente.");}
    private Caja validarCaja(UUID id,UUID sucursal){var p=TenantContext.principalActual();if(!com.citacloud.springboot.contacloud.app.security.EmpresaContext.permiteSucursal(sucursal))throw new RecursoNoEncontradoException("Sucursal no encontrada.");if(id==null)throw new ReglaNegocioException("Selecciona una caja activa.");return cajas.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).filter(c->c.isActivo()&&c.getSucursalId().equals(sucursal)).orElseThrow(()->new ReglaNegocioException("Selecciona una caja activa de la sucursal."));}
    @Transactional(readOnly=true) @PreAuthorize("hasAuthority('agentes_impresion.crear')") public List<OpcionCaja> cajas(UUID sucursal){var p=TenantContext.principalActual();return cajas.findAllByTenantIdAndEmpresaIdAndActivoTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(c->c.getSucursalId().equals(sucursal)&&com.citacloud.springboot.contacloud.app.security.EmpresaContext.permiteSucursal(sucursal)).map(c->new OpcionCaja(c.getId(),c.getNombre())).toList();}
    @Transactional @PreAuthorize("hasAuthority('agentes_impresion.crear')") public void asignarCaja(UUID id,UUID cajaId){var p=TenantContext.principalActual();var a=agentes.bloquear(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("No se encontró el agente."));validarCaja(cajaId,a.getSucursalId());a.asignarCaja(cajaId);auditoria.registrar("PrintAgentCashRegisterAssigned","PrintAgent",id,"{}");}
    public record OpcionCaja(UUID id,String nombre){}
    private static String limpiar(String v){return v==null?"":v.trim();}private static int permitido(int size){return Set.of(10,20,50).contains(size)?size:10;}public record OpcionSucursal(UUID id,String nombre){}
}
